const item = $input.first().json;
const body = item.body ?? item;

const normalizeBaseUrl = (value, fallback) => {
  const finalValue = String(value || fallback || '').trim();
  return finalValue.replace(/\/$/, '');
};

const content = String(body.content ?? '').trim();
const senderType = body.sender?.type ?? body.sender_type ?? body.conversation?.meta?.sender?.type ?? '';
const messageType = body.message_type;
const isIncoming = messageType === 'incoming' || messageType === 0 || messageType === '0';
const isPrivate = Boolean(body.private);
const shouldInspect =
  body.event === 'message_created' &&
  isIncoming &&
  senderType === 'contact' &&
  !isPrivate &&
  content.length > 0;

const orderMatch =
  content.match(/(?:order\s*#?\s*|#)(\d{4,})\b/i) ||
  content.match(/\b(\d{5,})\b/);

return {
  route: shouldInspect ? 'process' : 'ignore',
  event: body.event ?? '',
  isIncoming,
  senderType,
  isPrivate,
  content_length: content.length,
  messageId: body.id ?? null,
  conversationId: body.conversation?.id ?? body.conversation_id ?? null,
  accountId: body.account?.id ?? body.account_id ?? null,
  inboxId: body.inbox?.id ?? body.inbox_id ?? body.conversation?.inbox_id ?? null,
  content,
  senderType,
  messageType,
  detectedOrderId: orderMatch ? orderMatch[1] : '',
  config: {
    chatwootBaseUrl: normalizeBaseUrl('', 'https://sac.famivita.com'),
    wooBaseUrl: normalizeBaseUrl('', 'https://famivita.com.br'),
    openAiModel: 'gpt-4.1-mini',
    processingMode: 'live',
    allowedPhoneNumbers: [],
    allowedLabels: [],
    allowedInboxIds: [],
    maxConversationMessages: 8,
    supportEmail: 'support@famivita.com',
    orderCreationEnabled: false
  }
};

const requestContext = $('Wrap Main Conversation Output3').first().json ?? {};
const agentReply = String(requestContext.mainConversationReply || '').trim();

const parseNumber = (value) => {
  const parsed = Number.parseFloat(String(value ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(parsed) ? parsed : null;
};
const normalizeText = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();
const normalizeInlineText = (value) => String(value || '').replace(/\s+/g, ' ').trim();
const formatMoney = (value) => {
  const parsed = parseNumber(value);
  return parsed === null ? null : `R$ ${parsed.toFixed(2).replace('.', ',')}`;
};
const formatPrice = (product) => {
  for (const candidate of [product?.effective_price, product?.sale_price, product?.price, product?.regular_price]) {
    const formatted = formatMoney(candidate);
    if (formatted) return formatted;
  }
  return null;
};
const looksPortuguese = (text) => /(?:\b(?:produtos?|preco|abaixo|acima|entre|pedido|quero|preciso|gostaria|tenho|posso|sim|nao|quantidade|email|ola|confirmar|criar|detalhes?|informacao|sobre|carrinho|link)\b)/i.test(String(text || ''));
const isPortuguese = looksPortuguese(requestContext.originalMessage);
const greetingName = String(requestContext.customerName || '').trim();
const greeting = greetingName ? (isPortuguese ? `Ola ${greetingName}!` : `Hello ${greetingName}!`) : (isPortuguese ? 'Ola!' : 'Hello!');
const sanitizeTitle = (product) => {
  const title = String(product?.title || '').trim();
  const titleLooksLikeUrl = /^https?:\/\//i.test(title);
  if (title && !titleLooksLikeUrl) return title;
  const url = String(titleLooksLikeUrl ? title : (product?.product_url || '')).trim();
  if (!url) return isPortuguese ? 'produto selecionado' : 'the selected product';
  const slug = url.split('/').filter(Boolean).pop() || url;
  return slug.replace(/\?.*$/, '').replace(/[-_]+/g, ' ').trim();
};
const formatRangeText = (priceFilter) => {
  const min = parseNumber(priceFilter?.min);
  const max = parseNumber(priceFilter?.max);
  if (min !== null && max !== null) return isPortuguese ? `entre R$ ${min.toFixed(2).replace('.', ',')} e R$ ${max.toFixed(2).replace('.', ',')}` : `between R$ ${min.toFixed(2).replace('.', ',')} and R$ ${max.toFixed(2).replace('.', ',')}`;
  if (max !== null) return isPortuguese ? `abaixo de R$ ${max.toFixed(2).replace('.', ',')}` : `below R$ ${max.toFixed(2).replace('.', ',')}`;
  if (min !== null) return isPortuguese ? `acima de R$ ${min.toFixed(2).replace('.', ',')}` : `above R$ ${min.toFixed(2).replace('.', ',')}`;
  return isPortuguese ? 'nessa faixa de preco' : 'in that price range';
};
const formatMissingFields = (fields) => {
  const uniqueFields = [...new Set(Array.isArray(fields) ? fields : [])];
  const mapPt = {
    product: 'o produto',
    quantity: 'a quantidade',
    email: 'o e-mail',
    variation: 'a opcao/tamanho',
    cpf: 'o CPF',
    address_1: 'o endereco',
    number: 'o numero',
    city: 'a cidade',
    state: 'o estado',
    postcode: 'o CEP',
  };
  const mapEn = {
    product: 'the product',
    quantity: 'the quantity',
    email: 'the email',
    variation: 'the option/size',
    cpf: 'the CPF/tax ID',
    address_1: 'the address',
    number: 'the address number',
    city: 'the city',
    state: 'the state',
    postcode: 'the postcode',
  };
  const labels = uniqueFields.map((field) => isPortuguese ? (mapPt[field] || field) : (mapEn[field] || field));
  if (labels.length <= 1) return labels[0] || '';
  return `${labels.slice(0, -1).join(', ')} ${isPortuguese ? 'e' : 'and'} ${labels[labels.length - 1]}`;
};
const formatOptionLine = (option, index) => {
  const title = sanitizeTitle(option);
  const variationLabel = String(option?.variation_label || '').replace(/^[-/\s]+/, '').trim();
  const priceText = formatPrice(option);
  const parts = [title];
  if (variationLabel && !/^https?:\/\//i.test(variationLabel) && !normalizeText(title).includes(normalizeText(variationLabel))) {
    parts.push(variationLabel);
  }
  let line = `${index + 1}. ${parts.join(' - ')}`;
  if (priceText) line += `: ${priceText}`;
  return line;
};
const getTitleSegments = (value) => String(value || '')
  .split(/\s+-\s+/)
  .map((segment) => segment.trim())
  .filter(Boolean);
const inferVariationFromRelatedTitles = (product, relatedProducts = []) => {
  const currentSegments = getTitleSegments(sanitizeTitle(product));
  if (currentSegments.length < 2 || !Array.isArray(relatedProducts) || relatedProducts.length < 2) {
    return '';
  }
  const siblingSegments = relatedProducts
    .map((entry) => getTitleSegments(sanitizeTitle(entry)))
    .filter((segments) => segments.length > 0);
  if (siblingSegments.length < 2) {
    return '';
  }

  let prefixCount = 0;
  while (prefixCount < currentSegments.length && siblingSegments.every((segments) => segments[prefixCount] === currentSegments[prefixCount])) {
    prefixCount += 1;
  }

  let suffixCount = 0;
  while (
    suffixCount < currentSegments.length - prefixCount &&
    siblingSegments.every((segments) => {
      const currentIndex = currentSegments.length - 1 - suffixCount;
      const siblingIndex = segments.length - 1 - suffixCount;
      return siblingIndex >= prefixCount && segments[siblingIndex] === currentSegments[currentIndex];
    })
  ) {
    suffixCount += 1;
  }

  const inferred = currentSegments.slice(prefixCount, currentSegments.length - suffixCount).join(' - ').trim();
  return inferred;
};
const formatVariationLabel = (product, relatedProducts = []) => {
  const variationLabel = String(product?.variation_label || '').replace(/^[-/\s]+/, '').trim();
  const inferredVariation = inferVariationFromRelatedTitles(product, relatedProducts);
  if (!variationLabel) return inferredVariation || (isPortuguese ? 'nao especificada' : 'not specified');
  if (/^https?:\/\//i.test(variationLabel)) return inferredVariation || (isPortuguese ? 'nao especificada' : 'not specified');
  const title = sanitizeTitle(product);
  if (title && normalizeText(title).includes(normalizeText(variationLabel))) {
    return variationLabel;
  }
  return inferredVariation || variationLabel;
};
const formatProductBlock = (product, index, options = {}) => {
  const title = sanitizeTitle(product);
  const variationLabel = formatVariationLabel(product, options.relatedProducts);
  const priceText = formatPrice(product) || (isPortuguese ? 'nao informado' : 'not available');
  const stockText = normalizeInlineText(product?.stock_status);
  const summaryText = normalizeInlineText(product?.summary);
  const url = String(product?.product_url || product?.product_query_url || '').trim() || '-';
  const cartUrl = String(product?.cart_url || product?.product_cart_url || '').trim() || '-';
  const labels = isPortuguese
    ? {
        name: 'Nome:',
        variation: 'Variacao:',
        price: 'Preco:',
        stock: 'Estoque:',
        summary: 'Resumo:',
        url: 'URL:',
        cart: 'Link direto para o carrinho:',
      }
    : {
        name: 'Name:',
        variation: 'Variation:',
        price: 'Price:',
        stock: 'Stock status:',
        summary: 'Summary:',
        url: 'URL:',
        cart: 'Add to cart URL:',
      };

  const lines = [
    `${index + 1}.`,
    `${labels.name} ${title}`,
    `${labels.variation} ${variationLabel}`,
    `${labels.price} ${priceText}`,
  ];

  if (options.includeStock && stockText) {
    lines.push(`${labels.stock} ${stockText}`);
  }
  if (options.includeSummary && summaryText) {
    lines.push(`${labels.summary} ${summaryText}`);
  }

  lines.push(`${labels.url} ${url}`);
  lines.push(`${labels.cart} ${cartUrl}`);
  return lines.join('\n');
};
const formatPriceMatchBlock = (product, index) => formatProductBlock(product, index);

const orderReview = requestContext.orderReview && typeof requestContext.orderReview === 'object' ? requestContext.orderReview : null;
const formatAddressSummary = (review) => {
  const address = review?.delivery_address || {};
  const lines = [];
  const firstLine = [address.address_1 || '', address.number || ''].filter(Boolean).join(', ');
  if (firstLine) lines.push(firstLine);
  if (address.neighborhood) lines.push(address.neighborhood);
  const cityState = [address.city || '', address.state || ''].filter(Boolean).join(' - ');
  if (cityState) lines.push(cityState);
  if (address.postcode) lines.push(address.postcode);
  return lines.join('\n');
};
const formatShippingSummary = (review) => {
  if (!review) return isPortuguese ? 'a calcular' : 'to be calculated';
  if (review.shipping_cost_known) {
    return review.shipping_cost === 0
      ? (isPortuguese ? 'Gratis' : 'Free')
      : (formatMoney(review.shipping_cost) || (isPortuguese ? 'a calcular' : 'to be calculated'));
  }
  return isPortuguese ? 'sera calculado na etapa de pagamento' : 'will be calculated at payment';
};

const orderStatus = String(requestContext.orderCreationStatus || '').trim();
const orderMissingFields = Array.isArray(requestContext.orderMissingFields) ? requestContext.orderMissingFields : [];
const orderProductTitle = sanitizeTitle({ title: requestContext.orderDraftProductTitle, product_url: requestContext.orderDraftProductUrl });
const orderEmail = String(requestContext.orderDraftEmail || '').trim();
const orderQuantity = Number.isFinite(Number(requestContext.orderDraftQuantity)) && Number(requestContext.orderDraftQuantity) > 0
  ? String(Number(requestContext.orderDraftQuantity))
  : '1';
const orderPayUrl = String(requestContext.orderPayUrl || '').trim();
const orderCreateErrorMessage = String(requestContext.orderCreateErrorMessage || '').trim();
const buildConfirmationSummary = () => {
  if (!orderReview) return '';
  const itemLines = (Array.isArray(orderReview.items) ? orderReview.items : []).map((item, index) => {
    const name = sanitizeTitle({ title: item.display_name || item.title, product_url: item.product_url });
    const unitPrice = formatMoney(item.unit_price);
    const lineTotal = formatMoney(item.line_total);
    const qty = Number.isFinite(Number(item.quantity)) && Number(item.quantity) > 0 ? String(Number(item.quantity)) : orderQuantity;
    let text = `${index + 1}. ${name}`;
    if (unitPrice) text += isPortuguese ? `\n   Quantidade: ${qty} x ${unitPrice}` : `\n   Quantity: ${qty} x ${unitPrice}`;
    if (lineTotal) text += isPortuguese ? `\n   Total do item: ${lineTotal}` : `\n   Item total: ${lineTotal}`;
    return text;
  });
  const subtotalText = formatMoney(orderReview.subtotal);
  const totalText = formatMoney(orderReview.total_amount);
  const shippingText = formatShippingSummary(orderReview);
  const addressText = formatAddressSummary(orderReview);
  const lines = [];
  lines.push(isPortuguese ? `${greeting} So para confirmar, este sera o seu pedido:` : `${greeting} Just to confirm, this will be your order:`);
  if (itemLines.length > 0) lines.push(itemLines.join('\n'));
  if (subtotalText) lines.push(isPortuguese ? `Subtotal dos produtos: ${subtotalText}` : `Products subtotal: ${subtotalText}`);
  lines.push(isPortuguese ? `Frete: ${shippingText}` : `Shipping: ${shippingText}`);
  if (totalText) {
    const totalLabel = orderReview.total_amount_is_estimate
      ? (isPortuguese ? 'Total estimado sem frete' : 'Estimated total without shipping')
      : 'Total';
    lines.push(`${totalLabel}: ${totalText}`);
  }
  if (orderEmail) lines.push(isPortuguese ? `E-mail: ${orderEmail}` : `Email: ${orderEmail}`);
  if (requestContext.orderDraftBillingCpf) lines.push(`CPF: ${requestContext.orderDraftBillingCpf}`);
  if (addressText) lines.push((isPortuguese ? 'Endereco de entrega:\n' : 'Delivery address:\n') + addressText);
  lines.push(isPortuguese
    ? 'Se estiver tudo certo, responda "confirmar" e eu criarei o pedido com o link de pagamento.'
    : 'If everything looks right, reply "confirm" and I will create the order and send the payment link.');
  return lines.join('\n\n');
};

const hasMeaningfulOptionTitle = (option) => {
  const title = sanitizeTitle(option);
  return Boolean(title && title !== 'the selected product' && title !== 'produto selecionado');
};
const orderVariationOptions = Array.isArray(requestContext.orderVariationOptions)
  ? requestContext.orderVariationOptions.slice(0, 4).filter((option) => hasMeaningfulOptionTitle(option))
  : [];
const productLookup = Array.isArray(requestContext.productLookup) ? requestContext.productLookup : [];
const primaryProduct = productLookup[0] || null;
const getOptionIdentity = (product) => String(product?.variation_id || product?.product_query_url || product?.product_url || product?.title || '').trim();
const detailProducts = (() => {
  if (!primaryProduct) return [];
  const primaryProductId = String(primaryProduct.product_id || '').trim();
  const relatedProducts = primaryProductId
    ? productLookup.filter((product) => String(product?.product_id || '').trim() === primaryProductId)
    : productLookup;
  const deduped = [];
  const seen = new Set();
  for (const product of (relatedProducts.length > 0 ? relatedProducts : [primaryProduct])) {
    const key = getOptionIdentity(product);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    deduped.push(product);
  }
  return deduped.slice(0, 6);
})();
const detailIntentRequested = /\b(detail|details|info|information|about|summary|ingredient|ingredients|detalhe|detalhes|informacao|informacoes|sobre)\b/i.test(String(requestContext.originalMessage || ''));
const explicitOrderIntentRequested = /\b(create|place|buy|purchase|order|checkout|pay later|payment link|link to pay|criar pedido|fazer pedido|quero pedir|quero comprar|comprar|pedido)\b/i.test(String(requestContext.originalMessage || ''));
const stripMarkdown = (value) => String(value || '')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$2')
  .replace(/\*+/g, '')
  .replace(/\s+$/gm, '')
  .trim();
const tokenizeTitle = (value) => normalizeText(value).replace(/[^a-z0-9]+/g, ' ').trim();
const findLookupProductForTitle = (title, fallbackIndex) => {
  const candidates = Array.isArray(productLookup) ? productLookup : [];
  const normalizedTitle = tokenizeTitle(title);
  const matched = normalizedTitle ? candidates.find((product) => {
    const productTitle = tokenizeTitle(sanitizeTitle(product));
    return productTitle.includes(normalizedTitle) || normalizedTitle.includes(productTitle);
  }) : null;
  if (matched) return matched;
  if (candidates[fallbackIndex]) return candidates[fallbackIndex];
  return null;
};
const normalizeAgentDetailReply = (text) => {
  const cleaned = stripMarkdown(text).replace(/\bRead more\b/gi, '').trim();
  if (!cleaned) return cleaned;
  const sections = cleaned.split(/\n(?=\d+\.\s+)/);
  sections.shift();
  const blocks = sections
    .map((section, index) => {
      const lines = section.split('\n').map((line) => line.trim()).filter(Boolean);
      if (lines.length === 0) return '';
      const firstLine = lines.shift();
      const titleMatch = firstLine.match(/^\d+\.\s*(.+)$/);
      const title = (titleMatch?.[1] || firstLine).trim();
      const fields = {};
      for (const rawLine of lines) {
        const line = rawLine.replace(/^-\s*/, '').trim();
        const fieldMatch = line.match(/^([^:]+):\s*(.+)$/);
        if (!fieldMatch) continue;
        const label = normalizeText(fieldMatch[1]);
        const value = fieldMatch[2].trim();
        if (!value) continue;
        if (label.includes('price') || label.includes('preco')) fields.price = value;
        else if (label.includes('stock')) fields.stock = value;
        else if (label.includes('summary') || label.includes('resumo')) fields.summary = value;
        else if (label.includes('product link') || label === 'url' || label.includes('link do produto')) fields.url = value;
      }
      const lookupProduct = findLookupProductForTitle(title, index);
      const variationLabel = lookupProduct
        ? formatVariationLabel(lookupProduct, detailProducts.length > 0 ? detailProducts : productLookup)
        : (isPortuguese ? 'nao especificada' : 'not specified');
      const cartUrl = String(lookupProduct?.cart_url || lookupProduct?.product_cart_url || '').trim() || '-';
      const url = fields.url || String(lookupProduct?.product_url || lookupProduct?.product_query_url || '').trim() || '-';
      const priceText = fields.price || formatPrice(lookupProduct) || '';
      const stockText = fields.stock || normalizeInlineText(lookupProduct?.stock_status);
      const summaryText = fields.summary || normalizeInlineText(lookupProduct?.summary);
      const blockLines = [
        `${index + 1}.`,
        `${isPortuguese ? 'Nome:' : 'Name:'} ${title}`,
        `${isPortuguese ? 'Variacao:' : 'Variation:'} ${variationLabel}`,
      ];
      if (priceText) blockLines.push(`${isPortuguese ? 'Preco:' : 'Price:'} ${priceText}`);
      if (stockText) blockLines.push(`${isPortuguese ? 'Estoque:' : 'Stock status:'} ${stockText}`);
      if (summaryText) blockLines.push(`${isPortuguese ? 'Resumo:' : 'Summary:'} ${summaryText}`);
      blockLines.push(`URL: ${url}`);
      blockLines.push(`${isPortuguese ? 'Link direto para o carrinho:' : 'Add to cart URL:'} ${cartUrl}`);
      return blockLines.join('\n');
    })
    .filter(Boolean);
  if (blocks.length === 0) return cleaned;
  const intro = blocks.length > 1
    ? (isPortuguese ? `${greeting} Aqui estao os detalhes das opcoes encontradas:` : `${greeting} Here are the details for the matching products:`)
    : (isPortuguese ? `${greeting} Aqui estao os detalhes de ${sanitizeTitle(detailProducts[0] || productLookup[0] || {})}:` : `${greeting} Here are the details for ${sanitizeTitle(detailProducts[0] || productLookup[0] || {})}:`);
  return [intro, ...blocks].filter(Boolean).join('\n\n');
};
const buildDetailReply = () => {
  if (detailProducts.length === 0) return '';
  const intro = detailProducts.length > 1
    ? (isPortuguese ? `${greeting} Aqui estao os detalhes das opcoes encontradas:` : `${greeting} Here are the details for the matching products:`)
    : (isPortuguese ? `${greeting} Aqui estao os detalhes de ${sanitizeTitle(detailProducts[0])}:` : `${greeting} Here are the details for ${sanitizeTitle(detailProducts[0])}:`);
  let closing = isPortuguese
    ? 'Se quiser, posso ajudar voce a escolher uma opcao ou criar o pedido.'
    : 'If you want, I can help you choose an option or create the order.';
  if (requestContext.orderConversationRequested) {
    if (orderVariationOptions.length > 1) {
      closing = isPortuguese
        ? 'Se quiser continuar a compra, me diga qual opcao ou tamanho voce quer.'
        : 'If you want to continue the order, tell me which option or size you want.';
    } else if (requestContext.orderCreationStatus === 'needs_info') {
      closing = isPortuguese
        ? 'Quando quiser continuar a compra, me envie os dados que faltam.'
        : 'When you want to continue the order, send me the missing details.';
    }
  }
  const blocks = detailProducts.map((product, index) => formatProductBlock(product, index, { includeStock: true, includeSummary: true, relatedProducts: detailProducts }));
  return [intro, ...blocks, closing].filter(Boolean).join('\n\n');
};

const cartLinkRequested = Boolean(requestContext.cartLinkRequested);
const bestProductCartUrl = String(requestContext.bestProductCartUrl || '').trim();
const bestProductUrl = String(requestContext.bestProductUrl || '').trim();
const bestProductName = String(requestContext.bestProductName || '').trim();

let reply = '';
if (detailIntentRequested && detailProducts.length > 0 && !explicitOrderIntentRequested) {
  reply = buildDetailReply();
}

if (!reply && requestContext.orderActionRequested) {
  if (orderStatus === 'created') {
    reply = isPortuguese
      ? `${greeting} Seu pedido de ${orderQuantity} unidade(s) de ${orderProductTitle} esta pronto. Voce pode concluir o pagamento por este link:\n${orderPayUrl}\n\nE-mail do pedido: ${orderEmail}`
      : `${greeting} Your order for ${orderQuantity} unit(s) of ${orderProductTitle} is ready. You can complete the payment using this link:\n${orderPayUrl}\n\nOrder email: ${orderEmail}`;
  } else if (orderStatus === 'awaiting_confirmation') {
    const emailSuffix = orderEmail ? (isPortuguese ? ` com o e-mail ${orderEmail}` : ` with the email ${orderEmail}`) : '';
    reply = buildConfirmationSummary() || (isPortuguese
      ? `${greeting} Seu pedido de ${orderQuantity} unidade(s) de ${orderProductTitle}${emailSuffix} esta pronto para ser criado. Responda "confirmar" para eu criar o pedido e enviar o link de pagamento.`
      : `${greeting} Your order for ${orderQuantity} unit(s) of ${orderProductTitle}${emailSuffix} is ready to be created. Reply "confirm" and I will create the order and send the payment link.`);
  } else if (orderStatus === 'create_failed') {
    reply = isPortuguese
      ? `${greeting} Nao consegui criar o pedido automaticamente desta vez.${orderCreateErrorMessage ? ` WooCommerce informou: ${orderCreateErrorMessage}.` : ''} Se quiser, responda "confirmar" para eu tentar novamente, ou eu posso encaminhar para o time em ${requestContext.supportEmail}.`
      : `${greeting} I couldn't create the order automatically this time.${orderCreateErrorMessage ? ` WooCommerce said: ${orderCreateErrorMessage}.` : ''} If you want, reply "confirm" and I will try again, or I can hand this over to our team at ${requestContext.supportEmail}.`;
  } else if (orderStatus === 'needs_shipping_quote') {
    reply = isPortuguese
      ? `${greeting} Ainda nao consegui calcular o frete para esse CEP, entao nao vou criar o pedido sem o valor do frete. Confira o CEP e o endereco informado. Se quiser, eu tambem posso encaminhar para o time em ${requestContext.supportEmail}.`
      : `${greeting} I still couldn't calculate shipping for this CEP/postcode, so I won't create the order without the shipping charge. Please check the postcode and address you sent. If you want, I can also hand this over to our team at ${requestContext.supportEmail}.`;
  } else if (orderStatus === 'needs_info') {
    const billingFields = ['cpf', 'address_1', 'number', 'city', 'state', 'postcode'];
    const missingBillingFields = orderMissingFields.filter((field) => billingFields.includes(field));
    if (orderMissingFields.includes('variation') && orderVariationOptions.length > 0) {
      const optionsText = orderVariationOptions.map((option, index) => formatOptionLine(option, index)).join('\n');
      const remaining = orderMissingFields.filter((field) => field !== 'variation');
      reply = isPortuguese
        ? `${greeting} Encontrei mais de uma opcao para ${orderProductTitle}. Antes de criar o pedido, escolha uma opcao:\n${optionsText}${remaining.length ? `\n\nDepois disso, tambem preciso de ${formatMissingFields(remaining)}.` : `\n\nDepois disso, responda "confirmar" para eu criar o pedido.`}`
        : `${greeting} I found more than one option for ${orderProductTitle}. Before I create the order, choose one option:\n${optionsText}${remaining.length ? `\n\nAfter that, I also need ${formatMissingFields(remaining)}.` : `\n\nAfter that, reply "confirm" and I will create the order.`}`;
    } else if (missingBillingFields.length > 0) {
      const otherMissing = orderMissingFields.filter((field) => !billingFields.includes(field));
      const intro = isPortuguese
        ? `${greeting} Para criar o pedido, ainda preciso${otherMissing.length ? ` de ${formatMissingFields(otherMissing)} e ` : ' '}dos dados de faturamento: ${formatMissingFields(missingBillingFields)}.`
